Trigger.TriggerText:
BEGIN
   IF :CONTROL.SEARCH_NAME IS NULL THEN
      SET_BLOCK_PROPERTY('EMP', DEFAULT_WHERE, '');
   ELSE
      -- The search text is passed as a bind variable, never pasted into the SQL.
      SET_BLOCK_PROPERTY('EMP', DEFAULT_WHERE,
         'UPPER(last_name) LIKE UPPER(:CONTROL.SEARCH_NAME) || ''%''');
   END IF;
   GO_BLOCK('EMP');
   EXECUTE_QUERY;
   IF :EMP.EMP_ID IS NULL THEN
      MESSAGE('No employees match "' || :CONTROL.SEARCH_NAME || '".');
   END IF;
END;

BEGIN
   :CONTROL.SEARCH_NAME := NULL;
   SET_BLOCK_PROPERTY('EMP', DEFAULT_WHERE, '');
   GO_BLOCK('EMP');
   EXECUTE_QUERY;
END;

BEGIN
   GO_BLOCK('EMP');
   IF :SYSTEM.CURSOR_RECORD = '1' THEN
      MESSAGE('Already at the first employee.');
   ELSE
      PREVIOUS_RECORD;
   END IF;
END;

BEGIN
   -- Non-database item calculated for each fetched row.
   :EMP.FULL_NAME := :EMP.FIRST_NAME || ' ' || :EMP.LAST_NAME;
END;

ProgramUnit.ProgramUnitText:
PROCEDURE filter_by_department(p_dept IN VARCHAR2) IS
BEGIN
   -- Apply department filter to the EMP block and re-query
   COPY(NULL, 'CONTROL.SEARCH_NAME');
   IF p_dept IS NULL OR p_dept = 'ALL' THEN
      SET_BLOCK_PROPERTY('EMP', DEFAULT_WHERE, '');
   ELSE
      SET_BLOCK_PROPERTY('EMP', DEFAULT_WHERE, 'UPPER(department) = UPPER(''' || p_dept || ''')');
   END IF;
   GO_BLOCK('EMP');
   EXECUTE_QUERY;
END;

PROCEDURE apply_merit_raise(p_pct IN NUMBER) IS
   v_sal NUMBER;
BEGIN
   -- Increase the current employee salary by p_pct percent using NAME_IN / COPY
   IF NAME_IN('EMP.EMP_ID') IS NOT NULL THEN
      v_sal := ROUND(TO_NUMBER(NAME_IN('EMP.SALARY')) * (1 + (p_pct / 100)), 2);
      COPY(TO_CHAR(v_sal), 'EMP.SALARY');
      MESSAGE('Applied ' || TO_CHAR(p_pct) || '% merit increase to ' || NAME_IN('EMP.FULL_NAME') || '. Click Save to commit.');
   END IF;
END;

PROCEDURE promote_employee IS
   v_title VARCHAR2(200);
BEGIN
   v_title := NAME_IN('EMP.JOB_TITLE');
   IF NAME_IN('EMP.EMP_ID') IS NOT NULL AND INSTR(UPPER(v_title), 'SENIOR') = 0 THEN
      COPY('Senior ' || v_title, 'EMP.JOB_TITLE');
      MESSAGE('Promoted ' || NAME_IN('EMP.FULL_NAME') || ' to Senior ' || v_title || '.');
   END IF;
END;

Trigger.TriggerText:
BEGIN
   -- Show every employee when the form opens.
   GO_BLOCK('EMP');
   EXECUTE_QUERY;
END;
